                 'Создайте .env по .env.example.',
                 'Выполните alembic upgrade head на пустой database.',
                 'Запустите API командой из README.',
                 'Через Postman или Swagger создайте Category и две Task.',
                 'Получите list с фильтрами, sorting, limit и offset.',
                 'Обновите одну Task и удалите другую.',
                 'Спровоцируйте duplicate slug и проверьте 409, затем выполните корректный POST.',
